CREATE TABLE IF NOT EXISTS orders(ref TEXT PRIMARY KEY, email TEXT NOT NULL, items TEXT NOT NULL, usd_total REAL NOT NULL, ngn_kobo INTEGER NOT NULL, rate REAL NOT NULL, rate_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, paid_at INTEGER, paystack_id TEXT, note TEXT);
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY, event TEXT, ref TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS prompts(product_id TEXT PRIMARY KEY, content TEXT NOT NULL, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS kv(k TEXT PRIMARY KEY, v REAL, at INTEGER);
CREATE TABLE IF NOT EXISTS rate_limits(k TEXT PRIMARY KEY, n INTEGER NOT NULL, exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL, name TEXT, email TEXT, status TEXT NOT NULL DEFAULT 'new', unread_admin INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, last_message_at INTEGER NOT NULL, last_sender TEXT);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT, conv_id TEXT NOT NULL, sender TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_conv ON messages(conv_id,id);
CREATE INDEX IF NOT EXISTS idx_conv_last ON conversations(last_message_at);
